    [36] = "att=162690\031nm=i162690\031te=i162690\031dn=f52922\031ad=80001\031me=a62189\031gr=complete\031ph=1:481,2:482,22:483,25:484,29:485\031st=n=1\028ac=say\028fg=52829\028ne=f52828\028sa=176\028ti=486\028mn=p2352\029n=2\028ac=click\028ob=294096\028fg=52830\028at=542,355,320\028ne=#1\029n=3\028ac=click\028ob=294097\028fg=52831\028at=37,175,565\028ne=#2\029n=4\028ac=click\028ob=294098\028fg=52898\028at=542,535,108\028ne=#3\029n=5\028ac=click\028ob=294099\028fg=52899\028at=105,336,582\028ne=#4\029n=6\028ac=click\028ob=294100\028fg=52900\028at=542,679,410\028ne=#5\029n=7\028ac=click\028ob=294101\028fg=52901\028at=539,457,262\028ne=#6\029n=8\028ac=click\028ob=294102\028fg=52902\028at=104,516,438\028ne=#7\029n=9\028ac=click\028ob=294103\028fg=52903\028at=51,580,316\028ne=#8\029n=10\028ac=click\028ob=294104\028fg=52904\028at=23,240,780\028ne=#9\029n=11\028ac=click\028ob=294105\028fg=52905\028at=42,412,789\028ne=#10\029n=12\028ac=click\028ob=294106\028fg=52906\028at=33,779,443\028ne=#11\029n=13\028ac=click\028ob=294107\028fg=52907\028at=47,520,624\028ne=#12\029n=14\028ac=click\028ob=294108\028fg=52908\028at=25,446,264\028ne=#13\029n=15\028ac=click\028ob=294109\028fg=52909\028at=15,901,379\028ne=#14\029n=16\028ac=click\028ob=294110\028fg=52910\028at=17,368,276\028ne=#15\029n=17\028ac=click\028ob=294111\028fg=52911\028at=36,271,470\028ne=#16\029n=18\028ac=click\028ob=294112\028fg=52912\028at=125,428,202\028ne=#17\029n=19\028ac=click\028ob=294113\028fg=52913\028at=108,402,725\028ne=#18\029n=20\028ac=click\028ob=294114\028fg=52914\028at=241,171,579\028ne=#19\029n=21\028ac=click\028ob=294115\028fg=52915\028at=69,608,678\028ne=#20\029n=22\028ac=click\028ob=294312\028fg=52916\028at=14,854,736\028ne=#21\028sa=177\028ti=487\028mn=z14,n138578:488\029n=23\028ac=talk\028to=i82397?,i54474?,i21855?,i41519?\028np=138578\028fg=52917\028at=14,853,736\028ne=#22\028sa=178\028ti=489\029n=24\028ac=click\028ob=294314\028fg=52918\028at=14,853,737\028ne=#23\029n=25\028ac=emote\028to=i30569?,i1515?,i40360?,i22535?\028np=47121\028fg=52822\028at=241,285,249\028ne=#24\028sa=179\028ti=490\028mn=z241\029n=26\028ac=emote\028to=i30569?,i1515?,i40360?,i22535?\028np=36034\028fg=52823\028at=66,575,477\028ne=#24\028sa=180\028ti=491\028mn=z66\029n=27\028ac=emote\028to=i30569?,i1515?,i40360?,i22535?\028np=28792\028fg=52824\028at=121,406,687\028ne=#24\028sa=181\028ti=492\028mn=z121:493\029n=28\028ac=emote\028to=i30569?,i1515?,i40360?,i22535?\028np=62877\028fg=52826\028at=379,444,903\028ne=#24\028sa=182\028ti=494\028mn=z379\029n=29\028ac=talk\028np=138578\028fg=52919\028at=14,853,736\028ne=#25,#26,#27,#28\028sa=183\028ti=495\029n=30\028ac=click\028ob=294315\028fg=52920\028at=14,853,740\028ne=#29\029n=31\028ac=click\028ob=294335\028fg=52921\028at=14,884,692\028ne=#30\028sa=184\028ti=496\028mn=o294335:497\029n=32\028ac=talk\028np=138578\028at=14,853,736\028ne=#31\028sa=185\028ti=498\029n=33\028ac=click\028ob=294703\028fg=52922\028at=14,851,733\028ne=#32\028sa=186\028ti=499\028mn=o294703:500",
  },
  text = {
    [1] = "With the Weathered Relic in your bags, go back to Drak'thul and pick his first dialogue choice each time he speaks; the step ends once he only sends you away.",
    [2] = "Use the Dowser while on the platform. Stand with the grapple point behind you; the spike on your left holds the first rune, and the others follow clockwise. Swap the runes above the chest until they match, in four swaps at most.",
    [3] = "The Forging page lies deep inside the cave at the map marker.",
    [4] = "Pick up the Souls page from the platform at the map marker.",
    [5] = "A rune teleporter near the marker takes you up to the spot; the Binding page waits at its far side.",
    [6] = "Release the Feral Shadehound at the altar, then press the action buttons in the rune order your Crumbling Stele shows.",
    [7] = "Open the Immaculate Sac of Swog Treasures: it holds the Aquatic Shades, a toy to learn.",
    [8] = "Put on the Aquatic Shades (a toy), swim down to the Bubble Bath and keep dancing on its stage until the dancing debuff ends.",
    [9] = "With the Reshii Wraps equipped, step through the phase conduit; it takes you into Untethered Space.",
    [10] = "Hunt Hal'hadar Manatech near Manaforge Arcvein, on Normal difficulty, until one of them drops the Specimen Container Key; expect many kills.",
    [11] = "Open the Specimen Container inside the manaforge with the key, on Normal difficulty.",
    [12] = "You need the Torch of Pyrreth, from the Secrets of Azeroth questline, in almost every step below. Get it first if it is not yet in your bags.",
    [13] = "Pick the Detective title, which you earn with the achievement Azeroth's Greatest Detective, then talk to the Dalaran Survivor in Dornogal to start the hunt for Ratts.",
    [14] = "Enter the Pillar-nest Vosh cave beside Faerin's Advance. A hole high on one wall, which you can climb up to, drops into a hidden tunnel, and Ratts is at the end of it. Speak to him to finish the quest and receive the Peculiar Gem. Bring the three notes first.",
    [15] = "Stand at the gate of the Karazhan Catacombs in Deadwind Pass with the Peculiar Key in your bags and use the Torch of Pyrreth; a way opens into the Ratts' Revenge scenario, where the felcycle sits among twelve pillars.",
    [16] = "Hold your Torch at each of the three places below until a stack of the buff The Light of Their Love appears. With three stacks the first pillar lights.",
    [17] = "Hold the Torch at the Humble Monument in the Northern Barrens until a stack of the buff appears.",
    [18] = "Hold the Torch beside Decimator Olgra in Maldraxxus until a stack of the buff appears.",
    [19] = "Hold the Torch beside Olgra in Nagrand on Draenor until a stack of the buff appears. Where she stands depends on your quest progress; her other spot is at 74.2, 37.5.",
    [20] = "Summon a Perky Pug wearing one of the costumes and pick up the Gift of N'Zoth from one of the eyes. At the Ny'alotha obelisk in the Vale of Eternal Blossoms, use /pray. The Battle for Azeroth N'Zoth story must be finished.",
    [21] = "Dress your Perky Pug in the Dogg-Saron costume, which Vashti sells, or the Yipp-Saron costume, which comes from Hallow's End.",
    [22] = "Use a Twitching Eyeball or All-Seeing Eyes to get the Gift of N'Zoth buff.",
    [23] = "Open the chamber door in the room beside the Red Button with the Key of Shadows.",
    [24] = "In that room, cast your fishing line into the bowl on the left-hand bookcase; a key comes up.",
    [25] = "The key unlocks the chest in the same room. Inside are the Starry-Eyed Goggles: keep them on from here, since the consoles only show through them.",
    [26] = "Solve all nine decryption consoles below; each sits beside a chest that pays out one Piece of Hate. Keep all nine pieces, a later trade needs them.",
    [27] = "At the console beside this chest enter 88224646, press Submit, then open the chest.",
    [28] = "At the console beside this chest enter 17112317, press Submit, then open the chest.",
    [29] = "At the console beside this chest enter 1533, 3457, 8265 or 10638, press Submit, then open the chest. The goggles reveal this console.",
    [30] = "At the console beside this chest enter 19019, press Submit, then open the chest.",
    [31] = "At the console beside this chest enter 5661, press Submit, then open the chest.",
    [32] = "At the console beside this chest enter 52233, press Submit, then open the chest.",
    [33] = "At the console beside this chest enter 51567, press Submit, then open the chest.",
    [34] = "At the console beside this chest enter 115, press Submit, then open the chest.",
    [35] = "Any Feeling Lucky slot machine along the felcycle room walls works; enter 777, 888 or 168. It pays a Piece of Hate only if you carry five different lucky things, items or buffs. Thirteen lucky sources exist and the list here is only part of them. Stormwind sells three of them, and Griftah in Dornogal two.",
    [36] = "Use the scroll inside Uther's Tomb in the Western Plaguelands. A Doomguard appears and four pieces of graffiti become visible; interact with every one of them while the demon lives.",
    [37] = "Speak to Zarhym, a rare skull spirit near the cave mouth in the Cavern of Lost Spirits on the Timeless Isle, to cross into the spirit realm.",
    [38] = "Further into the cavern, Jeremy Feasel waits for a pet battle. Your team must be three level 25 secret pets (Baa'l, Snowclaw Cub and Taptaf are one team; Nelthara, Spyragos and Wicker Pup also count). Win, then talk to him for the Golden Muffin.",
    [39] = "Use the Torch at each of the five altars in Zul'Gurub, in Northern Stranglethorn, to call its spirit, then give that spirit everything it asks for.",
    [40] = "For the Sin spirit: wear any sinstone back cosmetic, summon the pet Sinheart and use the toy Bondable Sinstone.",
    [41] = "For the Corruption spirit: wear the Cloak of Overwhelming Corruption or a cloak that looks like it, use /cower on it, summon a mount and a pet that have corrupted in their names, and use the toy Ring of Broken Promises or Accursed Tome of the Sargerei.",
    [42] = "For the Void spirit: wear the Cloak of the Black Void or a cloak that looks like it, use /smirk on it, summon the pet Lesser Voidcaller, Sir Shady Mrrgglton Junior or Voidwiggler, and use the toy Shadowy Disguise or Void Totem.",
    [43] = "For the Lust spirit: take off your armor and clothes, use /flirt on it, summon the pet Sister of Temptation, and use the toy Moroes' Famous Polish or Steamy Romance Novel Kit.",
    [44] = "For the Blood spirit: summon a mount and a pet that have blood in their names, and use the toy Throbbing Blood Orb.",
    [45] = "Once every spirit is content, the Chest of Acquisitions sits against the wall close to the Shadow altar, visible only through the goggles. Open it for the Ancient Shaman Blood.",
    [46] = "Buy the Fledgling Warden Owl pet from this vendor (it needs Revered with the Wardens) and learn it; the owl must be out in step 21.",
    [47] = "Take your owl pet out on the Isle of the Watchers in Azsuna and stay with it in the glow of an owl statue that is lit up, until you hear a chime and see a magnifying glass over yourself. Four different glows count: red, green, blue and purple. When your owl carries a white orb above its head, it is finished.",
    [48] = "Empower the owl at a statue glow of a colour you have not done yet.",
    [49] = "Empower the owl at a statue glow of a colour you have not done yet.",
    [50] = "Empower the owl at a statue glow of a colour you have not done yet.",
    [51] = "Empower the owl at a statue glow of a colour you have not done yet.",
    [52] = "Run Vault of the Wardens at any difficulty and keep the owl out until the final boss. In Cordana's arena, take Elune's light from the glowing sentry statue and carry it back to where the dungeon begins; a door opens there, and the Sentry Statue stands in the middle of the room behind it.",
    [53] = "Take the statue to the Vault of Mirrors and put it down on the central platform that precedes the final staircase to Glazer.",
    [54] = "A grid of five by five statues appears. Interacting with one sinks it and toggles four others, and every statue has to end up sunk. Plan the clicks with a solver. When it is solved, loot the Warden's Mirror from the treasure.",
    [55] = "At the Enigma Machine, insert the Ancient Shaman Blood and the Warden's Mirror, press Begin once, then Submit: a random number of rats appears. Count the rats in the catacombs, leaving out the Catacombs Rats, then kill rats of both kinds so none steps on a plate. The machine has three locks.",
    [56] = "For each lock, turn the rat count into a plate and a number of statues, set that many statues on that plate, then press Submit.",
    [57] = "Plates 1 to 4: high in the felcycle room (71.6, 20.1); just inside its entrance (68.5, 34.2); past the locked east gate, opened with the Relic of Crystal Connections (73.6, 43.0); the corridor facing the felcycle room (68.8, 50.9).",
    [58] = "Plates 5 to 7: the flooded dead end near the catacombs entrance (73.6, 65.3); the corridor leading to the cat room (60.2, 71.6); a corner of the room where you caught the key (47.8, 78.9).",
    [59] = "Return to the Pillar-nest Vosh tunnel where Ratts was. Through the goggles a faint platform shows high above; the Relic of Crystal Connections on the humming crystal lifts you up. Type 84847078 at its console, press Submit, then open the chest beside it for the Keys to Incognitro.",
    [60] = "This continues Ratts' Revenge after the felcycle. Keep the Torch of Pyrreth and the Starry-Eyed Goggles from the first part, and note that these pillars came with a later patch.",
    [61] = "Bring a Bubblefilled Flounder: buy one on the Auction House, or catch the secret fish in the Hissing Grotto dive bar in the Waking Shores. That fish shows only to ghosts, so jump off a cliff and look around; it returns about every 45 seconds. With the Aquatic Shades on you can target it while alive.",
    [62] = "Put the egg down at the Duck Family beside Papa's Feather in Valdrakken and loot the Tuskarr Dinner Bell. When the duck family is not around, clicking the feather summons them.",
    [63] = "To'no wanders the Forbidden Reach and shows up at one of nine possible spots, but stays hidden until you step very close. Pick the second chat option for the Oddsight Focus; the first option pays random loot.",
    [64] = "In a group, go to the marked spot in southeastern Suramar and use the Torch until it shows a ghost that drifts around unseen. A button for the orb then appears on your screen; press it fast, since the ghost keeps moving.",
    [65] = "Carry the orb to Golk the Rumble in the middle of Azsuna. Whoever holds the orb has to stay on the ground, with no jumping, swimming or fighting, and sparking enemies keep attacking the holder, so bring a group.",
    [66] = "Speak to Golk with the orb. Everyone close by receives a Spare Key and a Weathered Lockbox.",
    [67] = "Open the Weathered Lockbox to learn Ensemble: Fashion of the Fanatic Felcyclist.",
    [68] = "Optional extra: carry the Spare Key and wear both the goggles and the Oddsight Focus buffs, and a footlocker becomes visible at the heart of the clock room in the catacombs. The key opens it and reveals Ratts' Journal, Page 317.",
    [69] = "You need water breathing and an aquatic mount, such as a Battle Turtle, Ottuk, Seahorse or Tidestallion. Atomized Salien Slime works well because it adds swim speed; a short questline in Azj-Kahet gives it. A Draenic Water Breathing Elixir, a Shimmerscale Diving Helmet, Aquatic Form, Touch of the Grave or Unending Breath also work.",
    [70] = "In Vashj'ir, go to the safe spot at the edge of the fatigue waters south of the Abyssal Depths and dive straight down from exactly there on your aquatic mount, nudging sideways a little to reset the fatigue. When the water turns from grey to dark blue, swim straight at the pearl that rests beside a submerged skeleton. Touch it by swimming into it; do not click it.",
    [71] = "The pearl carries you to the hidden Seat of Knowledge. If you have fewer than seventeen secrets, Jeremy Feasel there sets your Hearthstone to this version of the room.",
    [72] = "Once you have solved at least seventeen of the secrets shown here, talk to Anakron and choose I am ready. Only secrets you solved yourself count; Auction House purchases do not.",
    [73] = "The records on the left side of the stairs: Lost Obsidian Cache, Wicker Pup, Glimr, Tobias, Voidfire Deathcycle, Incognitro, Fashion of the Fanatic Felcyclist, and Leaders of Scholomance.",
    [74] = "The records on the right side of the stairs: Slime Serpent, Nazjatar Blood Serpent, Courage, Kosumoth the Hungering, Bound Shadehound, Riddler's Mind-Worm, Phoenix Wishwing, Gortham, and Sun Darter Hatchling.",
    [75] = "The records beside Anakron: Enlightened Hearthstone, Long-Forgotten Hippogryph, Wan'be's Buried Goods, Uuna's secret storyline, Xy Trustee's Gearglider, Baa'l, Waist of Time, Jenafur, Otto, Hand of Nilganihmaht, Mimiron's Jumpjets, Thrayir, Crimson Tidestallion, Sinrunner Blanchy, The Hivemind, and Lucid Nightmare.",
    [76] = "Reach Revered or better with The Tillers, then find the Lost Dog at the crossroads in the Heartland of the Valley of the Four Winds and take the quest Lost and Lonely. Turn it in with 20 Tasty T-Bones. Finishing it sends Dog to your Halfhill farm and rewards the Wooden Doghouse decor.",
    [77] = "Collect 20 Tasty T-Bone from the Skyrange Mushan in the Valley of the Four Winds.",
    [78] = "Build the Herb Garden in your Warlords of Draenor garrison; Dog then turns up beside it.",
    [79] = "Search the red cobblestone of the main streets of Dalaran in the Broken Isles for a Pebble. It is tiny and can lie in many spots, and the Auction House sells them as well.",
    [80] = "Take the Pebble to your garrison, find Dog by the Herb Garden and show it to him; never throw it at him. He then moves to the pet menagerie in Dalaran.",
    [81] = "In the Tranquil Strand on the Isle of Dorn, among the Dalaran ruins, click the half-buried dog bowl.",
    [82] = "Talk to Dog and choose to pet his head; he becomes your companion pet.",
    [83] = "Upstairs in Curiosities & Moore in Dalaran, read the Inconspicuous Note lying on the table.",
    [84] = "Inside Ulduar, reach XT-002 Deconstructor's room. Pull the lever in the northwest scrap corner, then light the big grid of lights so they draw a gear.",
    [85] = "In the Temple of Ahn'Qiraj, go past C'Thun's chamber to the side room with the Mind Larva on a table. Keep playing its brain game until it ends; a row of five brains does it.",
    [86] = "When the game is won, check the Mind Larva's table again: another Inconspicuous Note lies there. Read it.",
    [87] = "Wear the Shadoweave Mask itself (a transmog look of it does not count). In the Crumbling Depths of Deepholm, enter the Dark Fissure, read the Dingy Plaque behind the chair in the cave below, then interact with the Strange Skull that shows up on the seat.",
    [88] = "Another Inconspicuous Note is now on the ground before the chair. Read it.",
    [89] = "In Gnomeregan, find the ten numbered consoles near the Launch Bay and set them so they read 1222176597.",
    [90] = "In the abandoned house by Ash'theran in Val'sharah, use the Nightmare Tumor and untangle its lines until none of them cross.",
    [91] = "In Kun-Lai Summit, enter the Tomb of Secrets and use the urn at the back. In the Endless Halls, carry each of the five colored orbs, one at a time, to the rune of its color.",
    [92] = "Enter the Forgotten Crypt in Deadwind Pass and go down to the Pit of Criminals. Open Puzzler's Desire on the pile of bones to get the mount.",
    [93] = "In Dalaran's Legerdemain Lounge, read Page 9 on the bookcase in the first room, beside the painting.",
    [94] = "Twilight Grove in Duskwood: beside the moonwell stands a little table with Page 78 on it. Read it.",
    [95] = "Inside the Firelands raid, fight your way to Ragnaros' platform and read Page 161 at the back of its left side.",
    [96] = "In Uldum, ask Zidormi in Ramkahen for the Cataclysm version of the zone. Read Page 655 standing between two small trees near the coast, close to the Lost City of the Tol'vir.",
    [97] = "In Siege of Orgrimmar, reach the Sha of Pride; Page 845 lies in the back corner of his chamber, on the left as you enter. Getting to the raid needs the old version of the Vale of Eternal Blossoms.",
    [98] = "Inside the Well of Eternity dungeon, defeat the first two bosses and read Page 1127 at the foot of the stairs, beside a large stone divider.",
    [99] = "Near the Shado-Pan Monastery in Kun-Lai Summit, read Page 2351 at the base of a statue.",
    [100] = "Back in Uldum, still in the Cataclysm version, read Page 5555 at the foot of a statue in the group east of the Halls of Origination.",
    [101] = "On the Westfall coast, open the Gift of the Mind-Seekers lying in the wreck of a boat to get the mount.",
    [102] = "Collect 20 Abyssal Fragments. They drop from creatures across Kul Tiras and Zandalar, and other players sell them at the auction house.",
    [103] = "Take the 20 fragments to the Altar of the Abyss, at the end of the cave behind the waterfall in Stormsong Valley, and use it to make the essence.",
    [104] = "Take the essence to the Abyssal Icon in Saltstone Mine, in northern Stormsong Valley, and use it there to call the Adherent of the Abyss.",
    [105] = "In Nazmir, read the note on the high ledge beside the central temple. You can fly up to it.",
    [106] = "On the Broken Shore, click the pale pebble on the small stone table next to Drak'thul.",
    [107] = "In Boralus, climb down from the raised dock with the Homing Copter, walk through the net and the seaweed into the cave, and click the pale pebble on its floor.",
    [108] = "In Zuldazar, find the cave behind Atal'Dazar (outside the dungeon) and click the pebble at the foot of the tree root against the left wall.",
    [109] = "In Drustvar, follow the cave behind the narrow waterfall to its end. The pebble is tucked into the carved figure's skull; click it.",
    [110] = "In Vol'dun, find the cave mouth below the tall thin tree and click the pebble behind a small rock.",
    [111] = "In Stormsong Valley, fight through the pirates in the cave hidden among trees and click the pebble in the wheelbarrow.",
    [112] = "North of Nazmir, out at sea, dive to the sunken ship. In the stained glass at its stern, a row of pebbles curves below a skull: click the second one from the left. You need faster swimming to get there before the fatigue.",
    [113] = "In Boralus, near the hedge maze, the cellar behind the large tree holds stacked crates and a barrel. The pebble is out of sight at the back of that barrel; click it.",
    [114] = "On a small Drustvar island, stay out of the cave and jump onto the boulder at its mouth. The pebble sits on top, partly under creepers; click it.",
    [115] = "In Tiragarde Sound, drop into the hidden cave in the ground, where Clatterbacks leap out at you, and click the pebble wedged beside a rock in the gore.",
    [116] = "In Tiragarde Sound, go to the back of the cave behind the waterfall. A scroll lies open on the floor and the pebble is under it: stand over it, look up steeply with the camera, and click.",
    [117] = "Off the Boralus coast, swim through the seaweed into the underwater cave, reach the little island and click the pebble under the red kelp.",
    [118] = "At the northernmost tip of Vol'dun, swim down to the underwater cave and click the pebble just inside, ignoring the others.",
    [119] = "In Frostfire Ridge, Baa'l is in the volcano near Kurgthuk the Merciless. Call out a fully upgraded Uuna; she wears him down, and then you beat him in a pet battle.",
    [120] = "In Drustvar, click the unlit torches around the Hexed Chest to unlock it, then open it for the Bundle of Wicker Sticks.",
    [121] = "In Drustvar, open the Ensorcelled Chest for the Miniature Stag Skull.",
    [122] = "In Drustvar, click the unlit torches around the Enchanted Chest to unlock it, then open it for the Wolf Pup Spine.",
    [123] = "In Drustvar, click the unlit torches around the Bespelled Chest to unlock it, then open it for the Spooky Incantation.",
    [124] = "Use the four pieces together: they make the Spooky Bundle of Sticks, the item that teaches the pet.",
    [125] = "Talk to Amara Lunastar in eastern Ashenvale and tell her you will keep an eye out for her cat.",
    [126] = "Go into Donni Anthania's house in Elwynn Forest and look at the Empty Dish. If it is not there, talk to Amara Lunastar again.",
    [127] = "Inside Return to Karazhan, pick up eight foods: two Juicy Drumsticks, two Marbled Steaks, two Fishy Bits, a Meaty Morsel and a Slathered Rib. They lie in the Banquet Hall and the Guest Chambers. Each one disappears from your bags five minutes after you take it.",
    [128] = "In the Opera Hall, face away from the stage and lay the eight foods on the floor tiles, starting beside the two small kibble piles on the left and moving right: Juicy Drumstick, Marbled Steak, Fishy Bits, Meaty Morsel, Marbled Steak, Slathered Rib, Juicy Drumstick, Fishy Bits. Foods on the floor disappear after five minutes.",
    [129] = "Once the last food is down, Amara's Wish plays and Jenafur shows up in the hall. Go to her and pet her; she joins your pets.",
    [130] = "Click the Bone Effigy in Scavenger's Boneyard, with the Call of the Devourer and the three bones in your bags, to call the Many-Faced Devourer. Once you have done this, you can call it again whenever you like.",
    [131] = "Defeat this enemy for Uuna's Doll, then learn Uuna from the doll. It can be tried once a day.",
    [132] = "Call Uuna out and give her a moment: she greets you with one of three lines.",
    [133] = "Type /whistle at Uuna to get her attention.",
    [134] = "Type /roar at Uuna. She runs away, so summon her again.",
    [135] = "Type /cry at Uuna. She tells you the dark keeps her from seeing you properly.",
    [136] = "Walk Uuna up to A'dal in Shattrath; the Naaru's radiance overwhelms her and she bolts.",
    [137] = "Lead Uuna to Lake Falathim in Ashenvale so she can stand in its moonlight.",
    [138] = "Bring Uuna to Nuu, whose house sits on a small floating island off the far southwest of Eredath. It takes two glider jumps to get there.",
    [139] = "Bring Uuna to the Blood Watch outpost on Bloodmyst Isle.",
    [140] = "Take Uuna to the small camp in Draenor's Shadowmoon Valley; she picks up a wreath of flowers from a seat by the fire.",
    [141] = "Stay with her until void tendrils rise out of the earth and seize her.",
    [142] = "She can't be summoned now. Get yourself killed, talk to a Spirit Healer about Uuna to be let into the spirit realm, then run back to your body.",
    [143] = "Open the Shadow Tear in the Emerald Dragonshrine in Dragonblight. In the spirit realm, use /cheer on Uuna and put a Cooking Fire down next to her. For three minutes, run at the Soul-Eaters to scatter them; when she clutches herself and weeps, use /hug.",
    [144] = "Take Uuna to the Gate of the Setting Sun in the Vale of Eternal Blossoms. Ask Zidormi at the Seat of Knowledge for the older Vale first.",
    [145] = "Take Uuna to the Nighthold in Suramar.",
    [146] = "Take Uuna anywhere in Dalaran in the Broken Isles; Krasus' Landing works.",
    [147] = "Take Uuna to Wyrmrest Temple in Dragonblight.",
    [148] = "Take Uuna to Nordrassil on Mount Hyjal.",
    [149] = "Take Uuna to Neverest Pinnacle in Kun-Lai Summit.",
    [150] = "Take Uuna to Blackrock Mountain in the Burning Steppes.",
    [151] = "Take Uuna to the Temple of Karabor in Draenor's Shadowmoon Valley.",
    [152] = "Use Deal: Cartel Ba (only one Deal can be used each week, so all three drops take three weeks), then enter Manaforge Omega on any difficulty. After the first boss, take the right-hand path to the edge of the platform beside the teleporter to the central ring and loot the dead drop.",
    [153] = "Use Deal: Cartel Zo, then go to Mana-Vent Aphis in Manaforge Omega while Forgeweaver Araz is still alive. Walk the pipe that runs round the wall to its far end and loot the dead drop.",
    [154] = "Use Deal: Cartel Om, then head into Manaforge Omega beyond Fractillus. The dead drop sits on a boulder behind the building there.",
    [155] = "On the iceberg in the south of Grizzly Hills, chase the Glimmerfin Scout away and pick up the scale it leaves; that starts the quest chain.",
    [156] = "Defeat the Scuttleclaw Skimmers and Scuttleclaw Sandshells below the iceberg until you carry 10 Meaty Crab Chunks.",
    [157] = "Win a pet battle against Trainer Grrglin on his iceberg; he fields three aquatic pets.",
    [158] = "A Dark Iron Brewer in the Grim Guzzler, inside Blackrock Depths, leaves a Dire Brew behind once you have kept talking to him until he collapses.",
    [159] = "Make sure you own the battle pet Perky Pug, a reward of the achievement Looking for Multitudes; you will need to summon it later.",
    [160] = "The fire barrier lets through anyone who has drunk a Major Fire Protection Potion.",
    [161] = "The prismatic barrier needs protection from every school: drink a Major Frost, Holy, Nature and Shadow Protection Potion and one of the two Major Arcane Protection Potions, then walk through.",
    [162] = "The Diligent Watcher only notices the living, so drink Noggenfogger Elixirs until you have become a skeleton before you pass it.",
    [163] = "Scotty's Lucky Coin turns you into a sprite small enough for the wall of vines on the right. A Water Stone lies in the water beyond; take it.",
    [164] = "Activate the Water Stone and carry it back to the blue barrier, which then lets you through.",
    [165] = "Only dwarves get past the Stone Watcher, so drink a Dire Brew before you walk by.",
    [166] = "Upstairs, the right-hand path ends at a see-through barrier; Ethereal Oil makes you ghostly enough to reach the Strange Stone behind it.",
    [167] = "The Strange Stone's hole is fist-shaped and wants someone bigger: use a Gordok Ogre Suit together with a Winterfall Firewater, then put your arm in. You gain the Sign of the Second.",
    [168] = "Head back to the gate and drink Pygmy Oil until you are small enough to pass, then follow the left-hand path to the Wisdom Cube.",
    [169] = "Stand at the Wisdom Cube with your Perky Pug out, dress the pug in the \"Little Princess\" Costume, then pick the option to rest your arm under the cube. You gain the Sign of the First.",
    [170] = "In the last room downstairs, read the Tarnished Plaque on the pillar at your right. Cancel your Winterfall Firewater buff, then use a Scroll of Intellect.",
    [171] = "Past the plaque the floor dips into a pool. Walk into the water there (no jumping or swimming), cross to the far side and loot the Oddly-Colored Egg.",
    [172] = "Visit Ve'nari at her refuge in the Maw. She shows as a hologram now, with a new line of dialogue to pick.",
    [173] = "Travel to the Creation Catalyst in Zereth Mortis, where her body lies, and examine it through the dialogue choice.",
    [174] = "A few days later a message from Ve'nari reaches your mailbox with the toy inside.",
    [175] = "Climb the hill to the Blacktalon Shadowclaw, throw a Sour Apple at it, then ride it up the mountain.",
    [176] = "Call Baa'l out of your battle pet collection, on the character who defeated him.",
    [177] = "Visit Zidormi to see the Arathi Highlands as they used to be; Grimmy's list of friends lies on a table in his house by the coast. Read it.",
    [178] = "Put on the four uncommon pieces named in the list (Windwool Hood, Deathsilk Shoulders, Netherweave Tunic, Frostwoven Leggings), speak to Grimmy and choose the answer that presents you as an old friend.",
    [179] = "Carry all four items to Aquinastrasz in the Twilight Highlands and use /slap on Aquinastrasz.",
    [180] = "Carry all four items to Karnum Marshweaver in Desolace and use /wave at him.",
    [181] = "Carry all four items to Noggra in Zul'drak and use /cheer at her.",
    [182] = "Carry all four items to the Stained Mug in Kun-Lai Summit and use /dance next to it.",
    [183] = "Visit Grimmy again; a new answer mentions the messages you sent to his enemies. Choose it.",
    [184] = "Outside, keep using the Rotten Potato until the stacking buff it gives you reads exactly 144.",
    [185] = "Back with Grimmy, ask him to judge your scent.",
    [186] = "Grimmy's Rusty Lockbox sits up the slope past his house; open it.",
